// the floor only writes this file if it does not already exist. The verifier-
// writer subagent enriches `test.skip` lines into real assertions; you can
// too. Do NOT delete the smoke test (it's the floor the verify gate trusts).
import { test, expect, type Locator, type Page } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, waitForWorkspaceReady } from './helpers';

// Poll for a locator across several fresh fetches. On the shared, heavily-
// loaded board this test runs against (it executes after every other spec file
// has already grown node 0's board), a mutate call's own refresh can lose a
// race with a concurrent subscription-driven refresh and briefly clobber state
// with a stale (pre-mutate) snapshot. A single reload can happen to catch that
// same stale moment, so reload-and-retry a few times — the write is durable on
// the node, so a fresh list_tasks/list_categories eventually surfaces it.
async function expectVisibleWithReloads(
  page: Page,
  locator: Locator,
  { reloads = 4, per = 15_000 }: { reloads?: number; per?: number } = {},
) {
  for (let i = 0; ; i++) {
    try {
      await expect(locator).toBeVisible({ timeout: per });
      return;
    } catch (e) {
      if (i >= reloads) throw e;
      await page.reload();
      await waitForWorkspaceReady(page);
    }
  }
}

test.describe(`anyone on the team: see all tasks grouped by category`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes. Kept intentionally
  // workspace-free — the create-or-join gate itself is a valid, error-free
  // post-auth render, so the floor doesn't depend on node-0 bootstrap.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`the board view always shows every active (non-archived) task organized under its current category`, async ({ page }) => {
    // This test does more sequential mutate round-trips (1 category + 2 tasks
    // + 1 archive + a reload-verify) than any other story spec, and it runs
    // after several earlier files have already grown the shared board — give
    // it real headroom above the config default instead of racing it.
    test.setTimeout(180_000);
    await createWorkspace(page);

    // The workspace this test runs in is shared across every spec file in the
    // suite (createWorkspace reuses node 0's first namespace/context), so other
    // files' categories already sit on this board. Use run-unique names and
    // resolve the category's real id from the rendered column's testid, so
    // every later assertion targets THIS column deterministically — and so
    // retries never collide or produce multi-match strict-mode errors.
    const stamp = Date.now();
    const categoryName = `General-${stamp}`;
    const activeTitle = `Write specs ${stamp}`;
    const archivedTitle = `Old task ${stamp}`;

    await page.getByTestId('field-name').fill(categoryName);
    await page.getByTestId('action-create_category').click();
    const categoryColumn = page.locator('[data-testid^="item-category-"]').filter({ hasText: categoryName });
    // The create call's own refresh can race a concurrent subscription-driven
    // refresh; if the slower response wins it briefly clobbers state with a
    // stale (pre-create) snapshot. Force fresh fetches instead of just waiting
    // longer for a render that may never come without one.
    await expectVisibleWithReloads(page, categoryColumn);
    const catTestId = (await categoryColumn.getAttribute('data-testid')) ?? '';
    const categoryId = catTestId.replace('item-category-', '');
    expect(categoryId).not.toEqual('');
    const targetColumn = page.locator(`[data-testid="item-category-${categoryId}"]`);

    // Create an active task placed directly into THIS category. The board form's
    // category <select> defaults to categories[0] on a shared board, so select
    // our category explicitly before submitting (same proven approach as the
    // create-issue spec) — this fixes the flaky reliance on the modal move.
    await page.getByTestId('field-title').fill(activeTitle);
    await page.getByTestId('field-assignee').fill('alice');
    await page.getByTestId('field-category_id').selectOption({ label: categoryName });
    await page.getByTestId('action-create_task').click();
    const taskCard = page.locator('[data-testid^="item-task-"]').filter({ hasText: activeTitle });
    // Same eventual-consistency guard as the category creation above: force
    // fresh fetches if the first refresh raced and lost, rather than only
    // waiting longer for a render that requires another sync event.
    await expectVisibleWithReloads(page, taskCard);

    // Criterion: the active task is organized under its current category.
    await expect(targetColumn.getByText(activeTitle)).toBeVisible({ timeout: 20_000 });

    // A second task that gets archived must disappear from the board entirely.
    await page.getByTestId('field-title').fill(archivedTitle);
    await page.getByTestId('field-assignee').fill('bob');
    await page.getByTestId('field-category_id').selectOption({ label: categoryName });
    await page.getByTestId('action-create_task').click();
    const oldTaskCard = page.locator('[data-testid^="item-task-"]').filter({ hasText: archivedTitle });
    await expectVisibleWithReloads(page, oldTaskCard);
    await oldTaskCard.click();
    const dialog = page.getByRole('dialog');
    await dialog.getByTestId('action-archive_task').click();
    await expect(dialog).toBeHidden({ timeout: 10_000 });
    await expect(oldTaskCard).toBeHidden({ timeout: 20_000 });

    // The grouping property holds on a fresh render, not just after the
    // mutating actions.
    await page.reload();
    await waitForWorkspaceReady(page);
    await expect(targetColumn.getByText(activeTitle)).toBeVisible({ timeout: 20_000 });
    await expect(page.locator('[data-testid^="item-task-"]').filter({ hasText: archivedTitle })).toHaveCount(0);
  });
});
